document.title = `${c.label} — demonstração fictícia | Wpnz`;
const metricCards = [0,2,4].map((i)=>`<div><small>${c.metric[i]}</small><strong>${c.metric[i+1]}</strong></div>`).join('');
const queueRows = c.queue.map((q)=>`<div class="queue-row"><strong>${q[0]}</strong><span>${q[1]}</span><em>${q[2]}</em></div>`).join('');
const products = c.products.map((p,i)=>`<div class="product"><div class="product-icon">${p[0]}</div><div><strong>${p[1]}</strong><small>${p[2]}</small></div><button class="js-demo-action" aria-label="Simular inclusão de ${p[1]}">+</button></div>`).join('');
const features = c.features.map((f)=>`<div class="feature-chip"><b>${f[0]}</b><span>${f[1]}</span></div>`).join('');
const tables = ['01','02','03','04','05','06','07','08'].map((n,i)=>`<button class="table-button ${i%3===1?'occupied':''}"><strong>${slug==='marmitaria'?'Pedido':'Mesa'} ${n}</strong><small>${i%3===1?'Em atendimento':'Livre'}</small></button>`).join('');

