const toast = document.querySelector('.toast');
let timer;
document.querySelectorAll('.js-demo-action').forEach((button)=>button.addEventListener('click',()=>{ toast.textContent='Simulação concluída. Nenhum pedido real foi enviado.'; toast.classList.add('show'); clearTimeout(timer); timer=setTimeout(()=>toast.classList.remove('show'),2800); }));
document.querySelectorAll('.table-button').forEach((button)=>button.addEventListener('click',()=>button.classList.toggle('active')));
document.querySelector('[data-scroll]')?.addEventListener('click',()=>document.querySelector('#operacao').scrollIntoView({behavior:'smooth'}));
document.querySelectorAll('.demo-links button').forEach((button)=>button.addEventListener('click',()=>{document.querySelectorAll('.demo-links button').forEach(b=>b.classList.remove('active'));button.classList.add('active');document.querySelector('#operacao').scrollIntoView({behavior:'smooth'});}));
